import json,re
from pathlib import Path
root=Path('eval/corpora/tamagai-2026-10-04')
pa='_bmad-output/planning-artifacts/'
prd=pa+'prds/prd-tamagai-2026-09-29/prd.md'
spine=pa+'architecture/architecture-tamagai-2026-10-03/ARCHITECTURE-SPINE.md'
cr=pa+'architecture/architecture-tamagai-2026-10-03/CHANGE-REQUESTS.md'
records=[prd,prd.replace('prd.md','addendum.md'),pa+'ux-designs/ux-tamagai-2026-09-30/DESIGN.md',pa+'ux-designs/ux-tamagai-2026-09-30/EXPERIENCE.md',spine,spine.replace('ARCHITECTURE-SPINE','ARCHITECTURE-OVERVIEW'),cr,pa+'briefs/brief-tamagai-2026-09-29/brief.md',pa+'briefs/brief-tamagai-2026-09-29/addendum.md']
tasks=json.loads(Path('eval/m1-tamagai/gold/dev.json').read_text())
texts={p:(root/p).read_text().splitlines() for p in records}
for t in tasks:
 for kind in ('evidence','forbidden'):
  for u in t[kind]:
   lines=(root/u['path']).read_text().splitlines()
   assert 1 <= u['start'] <= u['end'] <= len(lines),(t['id'],u)
print('32 TASKS: all evidence and forbidden paths/ranges valid')
for t in tasks:
 if not t['citations']:continue
 ident=t['id'];got=set()
 for p,lines in texts.items():
  for n,s in enumerate(lines,1):
   matched=False
   if ident=='C01':
    matched=bool(re.search(r'(?<"'!['"\\w-])AD-12(?"'!['"\\w-]|\\.\\d)',s)) or any(int(a)<=12<=int(b) for a,b in re.findall(r'(?<"'!['"\\w-])AD-(\\d+)\\s*[–…]\\s*(?:AD-)?(\\d+)(?"'!['"\\w-]|\\.\\d)',s))
    matched &= not (p==spine and n==369)
   elif ident=='C02':
    candidate=p==spine and (n==11 or s.startswith('- **Binds:**'))
    matched=candidate and (bool(re.search(r'(?<"'!['"\\w-])FR-7(?"'!['"\\w-]|\\.\\d)',s)) or any(int(a)<=7<=int(b) for a,b in re.findall(r'(?<"'!['"\\w-])FR-(\\d+)\\s*[–…]\\s*(?:FR-)?(\\d+)(?"'!['"\\w-]|\\.\\d)',s)) or 'all MVP FRs' in s)
   elif ident=='C03': matched='sleep-dim' in s and not (p.endswith('/DESIGN.md') and n==40)
   elif ident=='C04': matched=bool(re.search(r'(?<"'!['"\\w-])FR-7\\.3(?"'!['"\\w.-])',s))
   elif ident=='C05': matched=bool(re.search(r'(?<"'!['"\\w-])OQ-12(?"'!['"\\w-]|\\.\\d)',s)) and not (p==prd and n==1965)
   elif ident=='C06': matched=p==cr and s.startswith('|') and 'conditional' in s.rstrip('| ').rsplit('|',1)[-1].lower()
   if matched:got.add((p,n))
 gold={(u['path'],u['line']) for u in t['citations']['lines']}
 print(ident,'derived=',len(got),'missing=',sorted(got-gold),'extra=',sorted(gold-got))
 for p,n in sorted(got): print(p.rsplit('/',1)[-1]+':'+str(n),texts[p][n-1][:220])
print('\\nFORBIDDEN SPANS')
for t in tasks:
 for u in t['forbidden']:
  lines=(root/u['path']).read_text().splitlines()
  print(t['id'],u['path'],f\"{u['start']}-{u['end']}\", ' / '.join(lines[u['start']-1:u['end']])[:360])
PY"

